 partial class DataEditorForm {
  PixelChoiceList teamLibrary;
  public EditorProject ExportProject(){SaveCurrent();return new JavaScriptSerializer{MaxJsonLength=50000000}.Deserialize<EditorProject>(Json());}
  public void ImportProject(EditorProject value){project=value??new EditorProject();if(project.teams==null)project.teams=new List<TeamRecord>();if(project.trainers==null)project.trainers=new List<TrainerRecord>();if(project.pokemon==null)project.pokemon=new List<PokemonRecord>();path="";dirty=false;RefreshTree(project.trainers.Cast<object>().Concat(project.pokemon).FirstOrDefault());RefreshTeamLibrary();}
  void BuildTeamTab(){
   var page=Page("팀 데이터");var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55,Padding=new Padding(5)};page.Controls.Add(bar);
   bar.Controls.Add(Button("새 팀",100,()=>EditTeam(-1)));bar.Controls.Add(Button("선택 팀 편집",130,()=>EditTeam(teamLibrary.SelectedIndex)));bar.Controls.Add(Button("선택 팀 삭제",130,DeleteTeam));
   teamLibrary=new PixelChoiceList{Dock=DockStyle.Left,Width=410};var help=new PixelText{Dock=DockStyle.Fill,Text="배틀에 쓸 팀을 이름별로 보관합니다.\n\n팀마다 트레이너 1명, 포켓몬과 필드효과 1개를 넣을 수 있습니다.\n필드효과는 지형(그래스필드 등)과 별개이며 이름·심도·트리거·효과식을 저장합니다.\n\n서로 다른 두 팀의 필드효과를 가져오면 둘 다 장소 전체에 적용됩니다. 같은 내용은 하나로 합칩니다.\n포켓몬 데이터 수정 후에는 팀 편성을 다시 열어 확인하세요."};page.Controls.Add(help);page.Controls.Add(teamLibrary);help.BringToFront();RefreshTeamLibrary();
  }
  void RefreshTeamLibrary(){if(teamLibrary==null)return;int selected=teamLibrary.SelectedIndex;teamLibrary.Items.Clear();if(project!=null&&project.teams!=null)foreach(var team in project.teams)teamLibrary.Items.Add(team);if(teamLibrary.Items.Count>0)teamLibrary.SelectedIndex=Math.Max(0,Math.Min(selected,teamLibrary.Items.Count-1));}
  void EditTeam(int index){SaveCurrent();if(project.teams==null)project.teams=new List<TeamRecord>();TeamRecord old=index>=0&&index<project.teams.Count?project.teams[index]:null;using(var f=new TeamSetupForm(project,old))if(f.ShowDialog(this)==DialogResult.OK){if(old==null)project.teams.Add(f.Value);else project.teams[index]=f.Value;dirty=true;UpdateTitle();RefreshTeamLibrary();}}
  void DeleteTeam(){int index=teamLibrary==null?-1:teamLibrary.SelectedIndex;if(index<0||index>=project.teams.Count)return;if(GameDialog.Show(this,"선택한 팀 데이터를 삭제할까요?","팀 삭제",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;project.teams.RemoveAt(index);dirty=true;UpdateTitle();RefreshTeamLibrary();}
 }

 class PixelChoiceList:ListBox {
  public PixelChoiceList(){Font=Theme.Input();DrawMode=DrawMode.OwnerDrawFixed;ItemHeight=36;IntegralHeight=false;BackColor=Color.White;}
  protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;e.Graphics.FillRectangle(Brushes.White,e.Bounds);if(selected){Theme.Pixels(e.Graphics,Brushes.Black,new Rectangle(e.Bounds.X+2,e.Bounds.Y+2,e.Bounds.Width-4,e.Bounds.Height-4),new[]{2,1});if(SelectionMode==SelectionMode.One)Theme.Cursor(e.Graphics,e.Bounds.X+10,e.Bounds.Y+e.Bounds.Height/2,Color.White);}Theme.Text(e.Graphics,Items[e.Index].ToString(),Font,new Rectangle(e.Bounds.X+26,e.Bounds.Y,e.Bounds.Width-32,e.Bounds.Height),selected?Color.White:Color.Black,ContentAlignment.MiddleLeft);}
 }

 class TeamSetupForm:Form {
  public TeamRecord Value;PixelComboBox trainer,fieldDepth;ListBox members;PixelTextBox art,teamName,fieldName,fieldTrigger,fieldEffect;PixelCheckBox fieldEnabled;
  public TeamSetupForm(EditorProject p,TeamRecord old){Load+=(s,e)=>Theme.Enlarge(this);Text=old==null?"새 팀":"팀 편집";Size=new Size(1040,780);MinimumSize=new Size(860,650);Font=Theme.UI();BackColor=Color.White;StartPosition=FormStartPosition.CenterParent;
   teamName=new PixelTextBox{Dock=DockStyle.Top,Font=Theme.Input(),Text=old==null?"새 팀":old.name};trainer=Theme.Combo(p.trainers.Select(t=>t.name),"");trainer.Dock=DockStyle.Top;
   members=new PixelChoiceList{Dock=DockStyle.Fill,SelectionMode=SelectionMode.MultiSimple};foreach(var m in p.pokemon)members.Items.Add(m.name);
   art=new PixelTextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font(Fonts.AA,12)};
   var field=old==null||old.fieldEffect==null?new FieldEffectRecord():old.fieldEffect.Copy();fieldEnabled=new PixelCheckBox{Text="이 필드효과 사용",Dock=DockStyle.Fill,Checked=field.enabled,Font=Theme.Input()};fieldName=new PixelTextBox{Dock=DockStyle.Fill,Font=Theme.Input(),Text=field.name};fieldDepth=Theme.Combo(new[]{"없음","1","2","3","4","5"},field.depth<=0?"없음":field.depth.ToString());fieldTrigger=new PixelTextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Vertical,Font=Theme.Input(),Text=field.trigger};fieldEffect=new PixelTextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Vertical,Font=Theme.Input(),Text=field.effect};
   trainer.SelectedIndex=old==null||old.trainer==null?-1:p.trainers.FindIndex(x=>x.name==old.trainer.name);
   if(old!=null){if(old.trainer!=null)art.Text=old.trainer.asciiArt;for(int i=0;i<p.pokemon.Count;i++)members.SetSelected(i,old.members.Any(x=>Object.ReferenceEquals(x,p.pokemon[i])||x.name==p.pokemon[i].name));}
   trainer.SelectedIndexChanged+=(s,e)=>{if(trainer.SelectedIndex>=0)art.Text=p.trainers[trainer.SelectedIndex].asciiArt;};
   var import=new FlatButton{Text="파일에서 필드효과 가져오기",Dock=DockStyle.Fill};import.Click+=(s,e)=>ImportFieldEffect();var fieldTable=Theme.Table();Theme.Row(fieldTable,"사용",fieldEnabled);Theme.Row(fieldTable,"필드 이름",fieldName);Theme.Row(fieldTable,"심도",fieldDepth);Theme.Row(fieldTable,"트리거 조건",fieldTrigger);fieldTable.RowStyles[fieldTable.RowCount-1].Height=100;Theme.Row(fieldTable,"효과식",fieldEffect);fieldTable.RowStyles[fieldTable.RowCount-1].Height=130;Theme.Row(fieldTable,"가져오기",import);var fieldNote=Theme.Label("포텐셜과 같은 트리거·효과 문장을 사용합니다. 현재는 발동 시 장소에 나와 있는 모든 포켓몬을 대상으로 판정합니다.",60);fieldNote.ForeColor=Theme.Muted;Theme.Row(fieldTable,"대상",fieldNote);
   var tabs=new TabControl{Dock=DockStyle.Fill,ItemSize=new Size(120,30)};Theme.Tabs(tabs);var aaTab=new TabPage("트레이너 AA"){BackColor=Color.White,Padding=new Padding(8)};aaTab.Controls.Add(art);var fieldTab=new TabPage("필드효과"){BackColor=Color.White,AutoScroll=true};fieldTab.Controls.Add(fieldTable);tabs.TabPages.Add(aaTab);tabs.TabPages.Add(fieldTab);if(field.name.Length>0)tabs.SelectedTab=fieldTab;var content=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=315,FixedPanel=FixedPanel.Panel1};var memberPanel=new Panel{Dock=DockStyle.Fill,Padding=new Padding(8)};memberPanel.Controls.Add(members);memberPanel.Controls.Add(new PixelLabel{Text="참가 포켓몬 · 클릭으로 선택",Dock=DockStyle.Top,Height=36});members.BringToFront();content.Panel1.Controls.Add(memberPanel);content.Panel2.Controls.Add(tabs);
   var ok=new FlatButton{Text="팀 데이터 저장",Dock=DockStyle.Bottom,Height=50,Primary=true};ok.Click+=(s,e)=>{if(teamName.Text.Trim().Length==0){GameDialog.Show(this,"팀 이름을 입력하세요.");return;}if(trainer.SelectedIndex<0||members.SelectedIndices.Count<1){GameDialog.Show(this,"트레이너 1명과 포켓몬을 1체 이상 선택하세요.");return;}if(fieldEnabled.Checked&&fieldName.Text.Trim().Length==0){GameDialog.Show(this,"사용할 필드효과의 이름을 입력하세요.");tabs.SelectedTab=fieldTab;return;}var t=p.trainers[trainer.SelectedIndex];t.asciiArt=art.Text;int depth=fieldDepth.Text=="없음"?0:int.Parse(fieldDepth.Text);Value=new TeamRecord{name=teamName.Text.Trim(),trainer=t,members=members.SelectedIndices.Cast<int>().Select(i=>p.pokemon[i]).ToList(),fieldEffect=new FieldEffectRecord{enabled=fieldEnabled.Checked,name=fieldName.Text.Trim(),depth=depth,trigger=TriggerStructures.NormalizeLines(fieldTrigger.Text),effect=EffectNormalizer.NormalizeLines(fieldEffect.Text),raw=field.raw}};DialogResult=DialogResult.OK;};
   Controls.Add(content);Controls.Add(trainer);Controls.Add(new PixelLabel{Text="트레이너",Dock=DockStyle.Top,Height=32});Controls.Add(teamName);Controls.Add(new PixelLabel{Text="팀 이름",Dock=DockStyle.Top,Height=32});Controls.Add(new PixelLabel{Text="포켓몬 편성 · 트레이너 AA · 독립 필드효과",Dock=DockStyle.Top,Height=40});Controls.Add(ok);
   }
   void ImportFieldEffect(){var dialog=new OpenFileDialog{Filter="AA Battle 필드효과 (*.aabfield.json;*.json)|*.aabfield.json;*.json|모든 파일 (*.*)|*.*"};if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{var value=FieldEffectFile.Parse(File.ReadAllText(dialog.FileName,Encoding.UTF8));fieldEnabled.Checked=value.enabled;fieldName.Text=value.name;fieldDepth.SelectedItem=value.depth<=0?"없음":Math.Min(5,value.depth).ToString();fieldTrigger.Text=value.trigger??"";fieldEffect.Text=value.effect??value.raw??"";}catch(Exception ex){GameDialog.Show(this,"필드효과를 가져올 수 없습니다.\r\n"+ex.Message,"가져오기 오류");}}
  }

 static class FlowPreview {
  public static void Run(Database db,string path){
   var trainer=new TrainerRecord{name="회귀 트레이너",asciiArt="AA"};var source=new EditorProject();
   for(int side=0;side<2;side++){var team=new TeamRecord{name="보관 팀 "+(side+1),trainer=trainer,fieldEffect=new FieldEffectRecord{name="검은 심층",depth=3,trigger=TriggerStructures.TurnEndLabel,effect="자신의 「공격」이 오른다."}};int count=side==0?8:9;for(int n=0;n<count;n++){var p=new PokemonRecord{name="팀"+side+"-"+n,types=new List<string>{"노말"},moves=new List<string>{"방어"},stats=new StatsRecord{hp=100,attack=100,defense=100,spAttack=100,spDefense=100,speed=100}};team.members.Add(p);source.pokemon.Add(p);}source.teams.Add(team);}source.trainers.Add(trainer);
   var saved=new JavaScriptSerializer().Deserialize<EditorProject>(new JavaScriptSerializer().Serialize(source));if(saved.teams[1].members.Count!=9||saved.teams[0].trainer.asciiArt!="AA"||saved.teams[0].fieldEffect.depth!=3)throw new Exception("Unlimited team and field effect roundtrip failed");
   var selected=saved.teams.Take(2).ToArray();var all=selected.Select(t=>t.members.Select(p=>{string warning;return new Fighter(EditorBridge.ToPokemon(p,db,out warning));}).ToList()).ToArray();using(var battle=new MainForm(db)){battle.LoadTeams(selected,all,new[]{2,4});battle.AssertTeamSetup(7,8);battle.Show();Application.DoEvents();Capture(battle,path+".battle.png");battle.Close();}
   using(var leads=new LeadForm(all,"선발 선택")){leads.Show();Application.DoEvents();Capture(leads,path+".leads.png");leads.Close();}
   using(var start=new StartForm(db)){start.SetProjectForTest(saved);start.SetFileTeamForTest(0,saved.teams[1]);start.Show();Application.DoEvents();Capture(start,path+".start.png");start.Close();}
   using(var editor=new DataEditorForm()){editor.ImportProject(saved);editor.Show();Application.DoEvents();editor.SelectTabForTest(6);Capture(editor,path+".teams.png");editor.SelectTabForTest(7);Capture(editor,path+".states.png");editor.SelectTabForTest(8);Capture(editor,path+".implementations.png");editor.CloseForTest();}
   using(var setup=new TeamSetupForm(saved,saved.teams[0])){setup.Show();Application.DoEvents();Capture(setup,path+".setup.png");setup.Close();}
   using(var intro=new VersusForm(selected)){var timer=new Timer{Interval=1800};timer.Tick+=(s,e)=>{timer.Stop();Capture(intro,path+".versus.png");};intro.Shown+=(s,e)=>timer.Start();intro.ShowDialog();timer.Dispose();}
  }
  static void Capture(Form form,string path){Application.DoEvents();using(var b=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(path);}}
 }

 class StartForm:Form {
  Database db;EditorProject project=new EditorProject();GameMenu menu;PixelComboBox[] teamPick=new PixelComboBox[2];FlatButton[] teamLoad=new FlatButton[2];TeamRecord[] fileTeams=new TeamRecord[2];bool refreshingTeams;Rectangle[] teamWindows=new Rectangle[2];
  public StartForm(Database d){db=d;Text="포켓몬 AA 배틀";ClientSize=new Size(1100,740);MinimumSize=new Size(900,660);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.White;DoubleBuffered=true;Font=Theme.UI();KeyPreview=true;
   for(int i=0;i<2;i++){int side=i;teamPick[i]=Theme.Combo(new string[0],"");teamPick[i].Dock=DockStyle.None;teamPick[i].DropDownStyle=ComboBoxStyle.DropDownList;teamPick[i].SelectedIndexChanged+=(s,e)=>{if(!refreshingTeams)fileTeams[side]=null;RefreshTeamInfo(side);};teamLoad[i]=new FlatButton{Text="파일에서 팀 불러오기"};teamLoad[i].Click+=(s,e)=>LoadTeamFile(side);Controls.Add(teamPick[i]);Controls.Add(teamLoad[i]);}
   menu=new GameMenu{Items=new[]{"배틀 시작","팀 데이터 편집","상태·날씨·효과 도감"}};menu.Activated+=Choose;Controls.Add(menu);
   Shown+=(s,e)=>menu.Focus();Resize+=(s,e)=>Arrange();RefreshTeamChoices();Arrange();
  }
  void Choose(int item){if(item==0)Begin();else if(item==1){using(var f=new DataEditorForm()){f.ImportProject(project);f.ShowDialog(this);project=f.ExportProject();RefreshTeamChoices();}}else using(var f=new StateDexForm())f.ShowDialog(this);menu.Focus();}
  internal void SetProjectForTest(EditorProject p){project=p;RefreshTeamChoices();}
  internal void SetFileTeamForTest(int side,TeamRecord team){fileTeams[side]=team;refreshingTeams=true;teamPick[side].Items.Clear();teamPick[side].Items.Add(team.ToString());teamPick[side].SelectedIndex=0;refreshingTeams=false;RefreshTeamInfo(side);if(!Object.ReferenceEquals(SelectedTeam(side),team))throw new Exception("Start screen file team selection failed");}
  void RefreshTeamChoices(){var names=(project.teams??new List<TeamRecord>()).Select(x=>x.ToString()).ToArray();refreshingTeams=true;for(int side=0;side<2;side++){int old=teamPick[side].SelectedIndex;teamPick[side].Items.Clear();teamPick[side].Items.AddRange(names);if(names.Length>0)teamPick[side].SelectedIndex=Math.Min(old>=0?old:side,names.Length-1);fileTeams[side]=null;RefreshTeamInfo(side);}refreshingTeams=false;}
  TeamRecord SelectedTeam(int side){if(fileTeams[side]!=null)return fileTeams[side];int i=teamPick[side].SelectedIndex;return project.teams!=null&&i>=0&&i<project.teams.Count?project.teams[i]:null;}
  void RefreshTeamInfo(int side){Invalidate(teamWindows[side]);}
  void LoadTeamFile(int side){var dialog=new OpenFileDialog{Filter="AA Battle 데이터 (*.aabdata.json)|*.aabdata.json|JSON (*.json)|*.json"};if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{var loaded=new JavaScriptSerializer{MaxJsonLength=50000000}.Deserialize<EditorProject>(File.ReadAllText(dialog.FileName,Encoding.UTF8));var teams=loaded==null||loaded.teams==null?new List<TeamRecord>():loaded.teams.Where(x=>x!=null).ToList();if(teams.Count==0)throw new Exception("저장된 팀이 없습니다.");TeamRecord chosen=teams.Count==1?teams[0]:ChooseTeam(teams,side);if(chosen==null)return;fileTeams[side]=chosen;refreshingTeams=true;teamPick[side].Items.Clear();teamPick[side].Items.Add(chosen.ToString());teamPick[side].SelectedIndex=0;refreshingTeams=false;RefreshTeamInfo(side);}catch(Exception ex){GameDialog.Show(this,"팀 데이터를 불러올 수 없습니다.\r\n"+ex.Message,"불러오기 오류");}}
  TeamRecord ChooseTeam(List<TeamRecord> teams,int side){using(var form=new Form{Text=(side+1)+"팀 선택",Size=new Size(480,430),StartPosition=FormStartPosition.CenterParent,BackColor=Color.White}){var list=new PixelChoiceList{Dock=DockStyle.Fill};foreach(var team in teams)list.Items.Add(team);list.SelectedIndex=0;var ok=new FlatButton{Text="이 팀 불러오기",Dock=DockStyle.Bottom,Height=50,Primary=true,DialogResult=DialogResult.OK};form.Controls.Add(list);form.Controls.Add(ok);return form.ShowDialog(this)==DialogResult.OK?teams[list.SelectedIndex]:null;}}
  void Arrange(){int cw=ClientSize.Width,ch=ClientSize.Height;int w=Math.Min(440,(cw-180)/2),h=236,top=150;teamWindows[0]=new Rectangle(cw/2-60-w,top,w,h);teamWindows[1]=new Rectangle(cw/2+60,top,w,h);for(int side=0;side<2;side++){var r=teamWindows[side];teamPick[side].SetBounds(r.X+22,r.Y+50,r.Width-48,30);teamLoad[side].SetBounds(r.X+22,r.Y+88,r.Width-48,38);}int menuWidth=400,menuHeight=menu.PreferredHeight;menu.SetBounds((cw-menuWidth)/2,Math.Max(top+h+20,Math.Min(top+h+34,ch-menuHeight-56)),menuWidth,menuHeight);Invalidate();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;int cw=ClientSize.Width,ch=ClientSize.Height;Theme.Frame(g,new Rectangle(14,14,cw-28,ch-28),false);
   using(var title=Theme.UI(24)){const string name="포켓몬 AA 배틀";int textWidth=(int)g.MeasureString(name,title).Width;Theme.Text(g,name,title,new Rectangle(40,38,cw-80,60),Color.Black,ContentAlignment.MiddleCenter);Theme.Ball(g,cw/2-textWidth/2-58,48,38);Theme.Ball(g,cw/2+textWidth/2+20,48,38);}
   using(var small=Theme.UI(8)){Theme.Text(g,"POKEMON  ·  AA  BATTLE",small,new Rectangle(40,100,cw-80,24),Color.Black,ContentAlignment.MiddleCenter);
    for(int side=0;side<2;side++){var r=teamWindows[side];Theme.Frame(g,r);var head=new Rectangle(r.X+10,r.Y+10,r.Width-24,30);Theme.Pixels(g,Brushes.Black,head,new[]{1});Theme.Text(g,(side+1)+"P  ·  "+(side+1)+"팀",small,head,Color.White,ContentAlignment.MiddleCenter);var team=SelectedTeam(side);int y=r.Y+138;var line=new Rectangle(r.X+24,y,r.Width-52,24);
     if(team==null){Theme.Text(g,"팀 데이터를 선택하세요",small,line,Color.Black,ContentAlignment.MiddleLeft);continue;}
     Theme.Text(g,"트레이너  "+(team.trainer==null?"없음":team.trainer.name),small,line,Color.Black,ContentAlignment.MiddleLeft);line.Y+=26;int count=team.members==null?0:team.members.Count;Theme.Text(g,"포켓몬  "+count+"체",small,line,Color.Black,ContentAlignment.MiddleLeft);for(int j=0;j<Math.Min(count,12);j++)Theme.Ball(g,line.X+96+j*20,line.Y+4,15);line.Y+=26;bool field=team.fieldEffect!=null&&team.fieldEffect.enabled&&team.fieldEffect.name.Length>0;Theme.Text(g,"필드효과  "+(field?"《"+team.fieldEffect.name+"》":"없음"),small,line,Color.Black,ContentAlignment.MiddleLeft);}
    Theme.Text(g,"↑↓ 선택     ENTER 결정     마우스로도 고를 수 있습니다",small,new Rectangle(40,ch-50,cw-80,24),Color.Black,ContentAlignment.MiddleCenter);}
   using(var vs=Theme.UI(24))Theme.Text(g,"VS",vs,new Rectangle(cw/2-56,teamWindows[0].Y+teamWindows[0].Height/2-30,112,60),Color.Black,ContentAlignment.MiddleCenter);}
  void Begin(){try{var teams=new[]{SelectedTeam(0),SelectedTeam(1)};if(teams.Any(x=>x==null))throw new Exception("1팀과 2팀에서 저장 파일을 불러오거나 팀을 선택하세요.");if(teams.Any(x=>x.trainer==null||x.members==null||x.members.Count<1))throw new Exception("선택한 팀에 트레이너와 포켓몬이 필요합니다.");var problems=new List<string>();for(int side=0;side<2;side++)problems.AddRange(TeamRules.Check(teams[side]).Select(x=>(side+1)+"팀 · "+x));if(problems.Count>0&&GameDialog.Show(this,"4대자질 편성 규칙과 다른 부분이 있습니다.\n\n"+string.Join("\n",problems.Take(12))+(problems.Count>12?"\n… 외 "+(problems.Count-12)+"건":"")+"\n\n이대로 배틀을 시작할까요?","편성 규칙 확인",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;
    var fighters=teams.Select(t=>t.members.Select(m=>{string warning;var f=new Fighter(EditorBridge.ToPokemon(m,db,out warning,t.trainer));if(warning.Length>0)throw new Exception(m.name+": "+warning);f.AA=m.asciiArt;return f;}).ToList()).ToArray();using(var intro=new VersusForm(teams)){if(intro.ShowDialog(this)!=DialogResult.OK)return;}int[] leads;using(var pick=new LeadForm(fighters,"선발 선택")){if(pick.ShowDialog(this)!=DialogResult.OK)return;leads=pick.Selected;}using(var battle=new MainForm(db)){battle.LoadTeams(teams,fighters,leads);Hide();try{battle.ShowDialog();}finally{Show();}}
  }catch(Exception ex){GameDialog.Show(this,ex.Message,"배틀 준비");}}
 }

 class VersusForm:Form {
  TeamRecord[] teams;AAView[] arts=new AAView[2];Timer timer=new Timer{Interval=16};System.Diagnostics.Stopwatch watch=new System.Diagnostics.Stopwatch();int balls,maxBalls;
  public VersusForm(TeamRecord[] value){teams=value;maxBalls=Math.Max(teams[0].members.Count,teams[1].members.Count);Text="VS";ClientSize=new Size(1100,Math.Min(900,650+Math.Max(0,(maxBalls+9)/10-2)*32));StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;DoubleBuffered=true;for(int i=0;i<2;i++){arts[i]=new AAView{Art=teams[i].trainer.asciiArt??"",Size=new Size(440,420)};Controls.Add(arts[i]);}Shown+=(s,e)=>{watch.Start();timer.Start();};timer.Tick+=(s,e)=>TickIntro();FormClosed+=(s,e)=>timer.Dispose();}
  void TickIntro(){double sec=watch.Elapsed.TotalSeconds,p=Math.Min(1,sec/.85);int shift=(int)((1-p)*(1-p)*600);if(sec>=.85&&sec<1.1)shift=(int)(Math.Sin(sec*100)*10);arts[0].Location=new Point(30-shift,80);arts[1].Location=new Point(ClientSize.Width-470+shift,80);int next=Math.Min(maxBalls,Math.Max(0,(int)((sec-1)*12)));if(next>balls)System.Media.SystemSounds.Asterisk.Play();balls=next;Invalidate();double end=Math.Min(6,2.2+maxBalls*.06);if(sec>end){timer.Stop();DialogResult=DialogResult.OK;Close();}}
